import { messageDispatcher } from '@app/infrastructure/messageDispatcher';
import { MessageHandler } from '@app/infrastructure/types';
import { Actions } from '@app/actions/shared';
import { showToast } from '@content/components/customToast';

const showNotificationHandler: MessageHandler<
  Actions.ShowNotification
> = async (message) => {
  const notification = message.payload;
  showToast({
    title: notification.title,
    text: notification.description,
    type: 'localNotification',
    buttons: notification.buttons.map((button) => ({
      text: button.text,
      accent: true,
      onClick: async () => {
        await messageDispatcher.send({
          action: Actions.NotificationAction,
          payload: {
            actionType: button.action,
            url: button.url,
          },
        });
      },
    })),
  });
};

const init = () => {
  messageDispatcher.register(Actions.ShowNotification, showNotificationHandler);
};

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', init);
} else {
  init();
}
